#include <vector>

class Solution {
public:
    int maxOperations(std::vector<int>& nums) {
        int target = nums[0] + nums[1];
        int ans = 1;
        for (size_t i = 2; i + 1 < nums.size(); i += 2) {
            if (nums[i] + nums[i + 1] == target) ans++;
            else break;
        }
        return ans;
    }
};

class Solution {
    public int maxOperations(int[] nums) {
        int target = nums[0] + nums[1];
        int ans = 1;
        for (int i = 2; i + 1 < nums.length; i += 2) {
            if (nums[i] + nums[i + 1] == target) ans++;
            else break;
        }
        return ans;
    }
}

var maxOperations = function(nums) {
    const target = nums[0] + nums[1];
    let ans = 1;
    for (let i = 2; i + 1 < nums.length; i += 2) {
        if (nums[i] + nums[i + 1] === target) ans++;
        else break;
    }
    return ans;
